/bin/bash -lc "python3 - <<'PY'
from urllib.request import Request, urlopen
cases = [
    ('Ada', 'Platform', 'eu-west'),
    ('Lin', 'Design', 'ap-south'),
]
for member, team, region in cases:
    request = Request('http://localhost:3100/', headers={
        'Cookie': f'member={member}; team={team}',
        'x-region': region,
    })
    with urlopen(request) as response:
        body = response.read().decode('utf-8')
        print(member, response.status, response.headers.get('Content-Type'))
        for needle in ('Workspace', '12 active projects', 'Loading your workspace details', f'Welcome, {member}', f'Team: {team}', f'Region: {region}'):
            print(f'  {needle}: {needle in body}')
        for other in ({'Ada', 'Lin'} - {member}):
            print(f'  other member {other}: {f\"Welcome, {other}\" in body}')
PY"
